using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestMethod]
    public void FormatPhoneNumber_ValidDigits_FormatsCorrectly()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        StringAssert.StartsWith(result, "(555)");
        StringAssert.EndsWith(result, "-4567");
        Assert.AreEqual("(555) 123-4567", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    public void FormatPhoneNumber_WrongLength_Throws()
    {
        Assert.ThrowsException<ArgumentException>(() => _formatter.FormatPhoneNumber("123"));
    }

    [TestMethod]
    public void BuildGreeting_WithDefaultTitle_StartsWithDearMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        StringAssert.StartsWith(result, "Dear Mr.");
        StringAssert.EndsWith(result, "Smith,");
    }

    [TestMethod]
    public void BuildGreeting_WithCustomTitle_UsesTitle()
    {
        var result = _formatter.BuildGreeting("Johnson", "Dr.");

        StringAssert.StartsWith(result, "Dear Dr.");
        StringAssert.EndsWith(result, "Johnson,");
    }

    [TestMethod]
    public void BuildGreeting_NullOrWhiteSpace_Throws()
    {
        Assert.ThrowsException<ArgumentException>(() => _formatter.BuildGreeting(""));
        Assert.ThrowsException<ArgumentException>(() => _formatter.BuildGreeting("   "));
    }

    [TestMethod]
    public void GenerateSlug_SimpleTitle_ReturnsLowercaseHyphenated()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters_ReplacedWithHyphens()
    {
        var result = _formatter.GenerateSlug("C# is Great!!!");

        StringAssert.StartsWith(result, "c-");
        StringAssert.EndsWith(result, "great");
    }

    [TestMethod]
    public void GenerateSlug_LeadingTrailingSpaces_Trimmed()
    {
        var result = _formatter.GenerateSlug("  Some Title  ");

        Assert.AreEqual("some-title", result);
    }

    [TestMethod]
    public void GenerateSlug_NullOrWhiteSpace_Throws()
    {
        Assert.ThrowsException<ArgumentException>(() => _formatter.GenerateSlug(""));
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollar()
    {
        var result = _formatter.FormatCurrency(19.99m);

        StringAssert.StartsWith(result, "$");
        StringAssert.EndsWith(result, "19.99");
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_UsesSymbol()
    {
        var result = _formatter.FormatCurrency(5.5m, "€");

        StringAssert.StartsWith(result, "€");
        StringAssert.EndsWith(result, "5.50");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_FormatsWithSign()
    {
        var result = _formatter.FormatCurrency(-10m);

        StringAssert.StartsWith(result, "$-");
        StringAssert.EndsWith(result, "10.00");
    }
}
EOF
